export const getPostBySlug = (slug) => blogPosts.find((p) => p.slug === slug)

export const getRelatedPosts = (currentSlug, category, count = 3) => {
  return blogPosts
    .filter((p) => p.slug !== currentSlug && p.category === category)
    .slice(0, count)
    .concat(
      blogPosts
        .filter((p) => p.slug !== currentSlug && p.category !== category)
        .slice(0, Math.max(0, count - blogPosts.filter((p) => p.slug !== currentSlug && p.category === category).length))
    )
    .slice(0, count)
}
